INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000026d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the German healthcare system at B2","Use Gesundheitssystem vocabulary","Talk about statutory and private health insurance"],"explanation":{"intro":"Healthcare system vocabulary covers Germany''s statutory health insurance, dual system, and current challenges at B2.","culturalNote":"Deutsches Gesundheitssystem: Gesetzliche Krankenversicherung (GKV — statutory health insurance, ~90% of population, employer-employee contribution). Private Krankenversicherung (PKV — private health insurance, for civil servants and high earners). Key features: Hausarztprinzip (GP as gatekeeper), Kassenärztliche Vereinigung (statutory medical association), Krankenhausreform (hospital reform — DRG system, 2023-2024 Lauterbach reform). Challenges: Fachkräftemangel (healthcare worker shortage), Krankenkassendefizit (deficit), Digitalisierung, ländliche Versorgung (rural care). Key principle: Solidaritätsprinzip (solidarity — healthy pay for sick)."},"examples":[{"german":"Das deutsche Gesundheitssystem verbindet das Solidaritätsprinzip — alle zahlen gemäß ihrer Einkommens- und erhalten unabhängig davon gleiche Leistungen — mit dem Beitragsprinzip und gewährleistet damit eine weitgehend bedarfsgerechte Grundversorgung.","english":"The German healthcare system combines the solidarity principle — all pay according to their income and receive equal services regardless — with the contribution principle, and thereby guarantees a largely needs-based basic provision."},{"german":"Die parallele Existenz von gesetzlicher und privater Krankenversicherung führt zu Zugangsdifferenzierungen, die von Verfechtern des Einheitssystems als strukturelle Ungleichheit kritisiert werden.","english":"The parallel existence of statutory and private health insurance leads to access differentiations that are criticised by advocates of a single-payer system as structural inequality."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s dual health insurance system, solidarity principle, and healthcare challenges at B2."}}',
'{"items":[{"word":"das Solidaritätsprinzip","translation":"solidarity principle","pronunciation":"dahs zo-li-dah-ri-TÄT-sprin-tsip","example":"Solidaritätsprinzip."},{"word":"bedarfsgerecht","translation":"needs-based","pronunciation":"beh-DARF-geh-rekht","example":"Bedarfsgerechte Versorgung."},{"word":"gewährleisten","translation":"to guarantee/ensure","pronunciation":"geh-VÄR-lys-ten","example":"Grundversorgung gewährleisten."},{"word":"die Zugangsdifferenzierung","translation":"access differentiation","pronunciation":"dee TSOO-ganks-di-fe-ren-TSEER-oong","example":"Zugangsdifferenzierungen."},{"word":"der Verfechter","translation":"advocate/champion","pronunciation":"dayr fer-FEK-ter","example":"Verfechter des Einheitssystems."},{"word":"unabhängig davon","translation":"regardless (of it)","pronunciation":"oon-ap-HÄN-ikh dah-fon","example":"Unabhängig davon gleiche Leistungen."}]}',
'{"title":"Unabhängig davon — regardless (pronoun-based: unabhängig + davon = unabhängig of that)","pattern":"unabhängig davon = regardless (unabhängig = independent/regardless + davon = of that — davon replaces a previously mentioned factor; can also use: unabhängig davon, ob/wer/was — with subordinate clause)","explanation":"Unabhängig davon = regardless (of that) — pronoun form (davon refers back to the previous clause/factor: income level). Alle zahlen nach Einkommen und erhalten unabhängig davon gleiche Leistungen = All pay according to income and receive equal services regardless (i.e., regardless of how much they pay). Can be extended: unabhängig davon, ob man viel zahlt = regardless of whether one pays a lot. Compare: unabhängig von + noun (regardless of + noun), egal wie (no matter how — more colloquial), ohne Rücksicht auf (without regard to — more formal/pejorative).","examples":[{"sentence":"Er entschied sich unabhängig davon, was andere dachten.","translation":"He decided regardless of what others thought."},{"sentence":"Die Hilfe wird gewährt, unabhängig davon, ob man versichert ist.","translation":"The help is granted regardless of whether one is insured."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Bedarfsgerecht'' means?","options":["needs-based","demand-oriented","appropriate","adequate"],"correctAnswer":"needs-based"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The German healthcare system combines the solidarity principle — all pay according to their income and receive equal services regardless — with the contribution principle, and thereby guarantees a largely needs-based basic provision.","options":["Das deutsche Gesundheitssystem verbindet das Solidaritätsprinzip — alle zahlen gemäß ihrer Einkommens- und erhalten unabhängig davon gleiche Leistungen — mit dem Beitragsprinzip und gewährleistet damit eine weitgehend bedarfsgerechte Grundversorgung.","In Deutschland zahlen alle in die Krankenkasse ein und bekommen dafür Gesundheitsleistungen.","Das Solidaritätsprinzip bedeutet, dass alle gleiche medizinische Versorgung erhalten.","Das GKV-System finanziert sich durch Beiträge und gewährt Versicherten gleiche Leistungen."],"correctAnswer":"Das deutsche Gesundheitssystem verbindet das Solidaritätsprinzip — alle zahlen gemäß ihrer Einkommens- und erhalten unabhängig davon gleiche Leistungen — mit dem Beitragsprinzip und gewährleistet damit eine weitgehend bedarfsgerechte Grundversorgung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Hilfe wird gewährt, unabhängig davon, ob man versichert ___.","options":["ist","sein","wird","bleibt"],"correctAnswer":"ist"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He decided regardless of what others thought","wordBankItems":["Er","entschied","sich","unabhängig","davon",",","was","andere","dachten","."],"correctAnswer":"Er entschied sich unabhängig davon , was andere dachten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gewährleisten'' means?","options":["to guarantee/ensure","to safeguard","to provide","to secure"],"correctAnswer":"to guarantee/ensure"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000026e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss public health at B2","Use Öffentliche Gesundheit vocabulary","Talk about disease prevention and health policy"],"explanation":{"intro":"Public health vocabulary covers population health, prevention, and Germany''s public health response at B2.","culturalNote":"Öffentliche Gesundheit (public health, Volksgesundheit): Gesundheitsamt (public health authority — Kreisgesundheitsamt). Robert Koch-Institut (RKI — Germany''s federal public health agency, Berlin — epidemiology, infectious disease). COVID-19: lockdowns (Lockdown), Impfkampagne (vaccination campaign), 2G/3G rules, Bundestag debate on compulsory vaccination (Impfpflicht — not introduced). Public health traditions: Bismarckian welfare state (1883). WHO (World Health Organization — Geneva). Key concept: Prävention vs. Kuration (prevention vs. cure), Gesundheitsförderung (health promotion). Key indicator: Lebenserwartung (life expectancy)."},"examples":[{"german":"Öffentliche Gesundheitspolitik zeichnet sich dadurch aus, dass sie auf bevölkerungsweite Prävention statt auf individuelle Behandlung setzt — ein Ansatz, der im Spannungsfeld zwischen staatlicher Fürsorge und persönlicher Freiheit steht.","english":"Public health policy is characterised by the fact that it relies on population-wide prevention rather than individual treatment — an approach that stands in the tension between state care and personal freedom."},{"german":"Das Versagen nationaler und internationaler Surveillance-Systeme vor der COVID-19-Pandemie verdeutlicht, dass öffentliche Gesundheitsinfrastruktur als öffentliches Gut dauerhaft finanziert werden muss.","english":"The failure of national and international surveillance systems before the COVID-19 pandemic makes it clear that public health infrastructure must be permanently financed as a public good."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss public health, disease prevention, and Germany''s public health system at B2."}}',
'{"items":[{"word":"sich auszeichnen durch","translation":"to be characterised by","pronunciation":"zikh OWS-tsykh-nen doorkh","example":"Sich auszeichnen durch Prävention."},{"word":"bevölkerungsweit","translation":"population-wide","pronunciation":"beh-VÖL-ker-oonks-vyt","example":"Bevölkerungsweite Prävention."},{"word":"statt","translation":"instead of (prep.)","pronunciation":"shtat","example":"Statt Behandlung auf Prävention."},{"word":"das Versagen","translation":"failure","pronunciation":"dahs fer-ZAH-gen","example":"Das Versagen von Systemen."},{"word":"verdeutlichen","translation":"to make clear","pronunciation":"fer-DOYT-li-khen","example":"Verdeutlichen, dass."},{"word":"dauerhaft","translation":"permanently","pronunciation":"DOW-er-haft","example":"Dauerhaft finanzieren."}]}',
'{"title":"Sich dadurch auszeichnen, dass... — to be characterised by the fact that... (distinctive feature)","pattern":"etwas zeichnet sich dadurch aus, dass = something is characterised by the fact that (separable: zeichnet...aus; dadurch...dass = by (the fact that) — the correlative pair)","explanation":"Sich dadurch auszeichnen, dass = to be characterised by the fact that, to be distinguished by the fact that. Auszeichnen (separable: aus + zeichnen) = to distinguish/characterise (reflexive: sich auszeichnen durch/dadurch). Dadurch...dass = correlative pair: dadurch in the main clause, dass introducing the content clause. Öffentliche Gesundheitspolitik zeichnet sich dadurch aus, dass sie auf Prävention setzt = Public health policy is characterised by the fact that it relies on prevention. Compare: dadurch, dass (by the fact that — instrumental), indem (by [doing] — more manner-focused), durch + noun (by + noun — instrumental).","examples":[{"sentence":"Das Projekt zeichnet sich dadurch aus, dass es alle Beteiligten einbezieht.","translation":"The project is characterised by the fact that it involves all those concerned."},{"sentence":"Dieses Modell zeichnet sich dadurch aus, dass keine Gebühren anfallen.","translation":"This model is characterised by the fact that no fees are incurred."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verdeutlichen'' means?","options":["to make clear","to clarify","to demonstrate","to illustrate"],"correctAnswer":"to make clear"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Public health policy is characterised by the fact that it relies on population-wide prevention rather than individual treatment — an approach that stands in the tension between state care and personal freedom.","options":["Öffentliche Gesundheitspolitik zeichnet sich dadurch aus, dass sie auf bevölkerungsweite Prävention statt auf individuelle Behandlung setzt — ein Ansatz, der im Spannungsfeld zwischen staatlicher Fürsorge und persönlicher Freiheit steht.","Öffentliche Gesundheitspolitik schützt alle Bürger durch Vorsorge statt Behandlung.","Prävention ist günstiger als Behandlung und daher der bevorzugte Ansatz.","Gesundheitspolitik muss zwischen staatlicher Fürsorge und individueller Freiheit abwägen."],"correctAnswer":"Öffentliche Gesundheitspolitik zeichnet sich dadurch aus, dass sie auf bevölkerungsweite Prävention statt auf individuelle Behandlung setzt — ein Ansatz, der im Spannungsfeld zwischen staatlicher Fürsorge und persönlicher Freiheit steht."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Projekt zeichnet sich dadurch aus, dass es alle Beteiligten ___.","options":["einbezieht","mitnimmt","einlädt","beteiligt"],"correctAnswer":"einbezieht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This model is characterised by the fact that no fees are incurred","wordBankItems":["Dieses","Modell","zeichnet","sich","dadurch","aus",",","dass","keine","Gebühren","anfallen","."],"correctAnswer":"Dieses Modell zeichnet sich dadurch aus , dass keine Gebühren anfallen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Dauerhaft'' means?","options":["permanently","lasting","long-term","sustained"],"correctAnswer":"permanently"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000026f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss medical ethics at B2","Use Medizinethik vocabulary","Talk about bioethics, informed consent, and end-of-life issues"],"explanation":{"intro":"Medical ethics vocabulary covers bioethics principles, German healthcare ethics, and end-of-life debates at B2.","culturalNote":"Medizinethik: Key principles: Autonomie (autonomy — patient self-determination), Benefizienz (beneficence), Non-Malefizienz (non-maleficence), Gerechtigkeit (justice). Germany: Deutscher Ethikrat (German Ethics Council — advisory to Bundestag/Government on bioethics). Patientenverfügung (advance directive — legally binding since 2009). Sterbehilfe (assisted dying): Germany''s Bundesverfassungsgericht (2020) ruled right to assisted suicide exists but BtMG provisions struck down — new regulation unclear. Organ donation (Organspende): Germany switched to Widerspruchslösung (opt-out — 2020) after debate. Gentechnik (genetic engineering) ethics — CRISPR debates."},"examples":[{"german":"Das Prinzip der informierten Einwilligung verkörpert den Respekt vor der Patientenautonomie: Jede medizinische Maßnahme bedarf der aufgeklärten Zustimmung der betroffenen Person — es sei denn, sie ist nicht einwilligungsfähig.","english":"The principle of informed consent embodies respect for patient autonomy: every medical intervention requires the informed consent of the person concerned — unless they are not capable of consent."},{"german":"Die Debatte um aktive Sterbehilfe in Deutschland offenbart einen tiefen Wertkonflikt zwischen dem Recht auf Selbstbestimmung am Lebensende und dem Schutz vulnerabler Menschen vor gesellschaftlichem Druck.","english":"The debate about active assisted dying in Germany reveals a deep value conflict between the right to self-determination at the end of life and the protection of vulnerable people from social pressure."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss bioethics, informed consent, and Germany''s assisted dying debate at B2."}}',
'{"items":[{"word":"verkörpern","translation":"to embody","pronunciation":"fer-KÖR-pern","example":"Einen Respekt verkörpern."},{"word":"die Einwilligung","translation":"consent","pronunciation":"dee yn-VI-li-goong","example":"Informierte Einwilligung."},{"word":"einwilligungsfähig","translation":"capable of consent","pronunciation":"yn-VI-li-goonks-fä-ikh","example":"Einwilligungsfähig sein."},{"word":"offenbaren","translation":"to reveal","pronunciation":"O-fen-bah-ren","example":"Einen Konflikt offenbaren."},{"word":"vulnerabel","translation":"vulnerable","pronunciation":"vool-neh-RAH-bel","example":"Vulnerable Menschen."},{"word":"der Wertkonflikt","translation":"value conflict","pronunciation":"dayr VERT-kon-flikt","example":"Tiefer Wertkonflikt."}]}',
'{"title":"Es sei denn, ... — unless... (exception clause)","pattern":"es sei denn, (dass) = unless, except if (introduces an exception to the main clause; sei is subjunctive I of sein — formal, retained in fixed phrase even in spoken German)","explanation":"Es sei denn, (dass) = unless (es sei denn = let it be the case that [this exception applies]). Jede Maßnahme bedarf der Zustimmung, es sei denn, sie ist nicht einwilligungsfähig = Every measure requires consent, unless they are not capable of consent. Structure: main clause + , es sei denn, + exception clause (the exception clause can have dass — optional). The verb after es sei denn can use indicative or subjunctive I. Very formal — more formal than außer wenn (unless — more colloquial), außer in dem Fall, dass (except in the case that). Compare: sofern nicht (provided that... not), wenn nicht (if not — closer to unless in informal speech).","examples":[{"sentence":"Das Projekt wird wie geplant durchgeführt, es sei denn, es gibt unvorhergesehene Probleme.","translation":"The project will be carried out as planned, unless there are unforeseen problems."},{"sentence":"Alle Anträge werden bearbeitet, es sei denn, sie sind unvollständig.","translation":"All applications will be processed, unless they are incomplete."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verkörpern'' means?","options":["to embody","to represent","to express","to manifest"],"correctAnswer":"to embody"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The principle of informed consent embodies respect for patient autonomy: every medical intervention requires the informed consent of the person concerned — unless they are not capable of consent.","options":["Das Prinzip der informierten Einwilligung verkörpert den Respekt vor der Patientenautonomie: Jede medizinische Maßnahme bedarf der aufgeklärten Zustimmung der betroffenen Person — es sei denn, sie ist nicht einwilligungsfähig.","Ärzte dürfen ohne Einwilligung des Patienten nicht handeln.","Informierte Einwilligung ist der Kern der Patientenrechte.","Patienten haben das Recht, jede Behandlung abzulehnen."],"correctAnswer":"Das Prinzip der informierten Einwilligung verkörpert den Respekt vor der Patientenautonomie: Jede medizinische Maßnahme bedarf der aufgeklärten Zustimmung der betroffenen Person — es sei denn, sie ist nicht einwilligungsfähig."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Projekt wird durchgeführt, es sei denn, es gibt unvorhergesehene ___.","options":["Probleme","Hindernisse","Komplikationen","Schwierigkeiten"],"correctAnswer":"Probleme"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: All applications will be processed unless they are incomplete","wordBankItems":["Alle","Anträge","werden","bearbeitet",",","es","sei","denn",",","sie","sind","unvollständig","."],"correctAnswer":"Alle Anträge werden bearbeitet , es sei denn , sie sind unvollständig ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vulnerabel'' means?","options":["vulnerable","susceptible","at-risk","fragile"],"correctAnswer":"vulnerable"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000270',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss mental health at B2","Use Psychische Gesundheit vocabulary","Talk about mental health stigma and care in Germany"],"explanation":{"intro":"Mental health vocabulary covers psychiatric care, stigma, and mental health policy in Germany at B2.","culturalNote":"Psychische Gesundheit in Deutschland: prevalence: ~33% of Germans experience a mental health condition (Burnout, Depression, Angststörungen). Key concepts: Stigmatisierung (stigma — still a barrier to seeking help). Key institutions: Psychiatrische Kliniken (psychiatric hospitals), niedergelassene Psychiater (outpatient psychiatrists), Psychotherapeuten (psychotherapists — statutory funding, long waiting times). Burnout debate (work stress culture — Leistungsgesellschaft). Depression: WHO major cause of disability globally. Key policy: Reformpsychiatrie (reform psychiatry — deinstitutionalisation, community care). Suizidprävention (suicide prevention). COVID: mental health impacts."},"examples":[{"german":"Psychische Erkrankungen sind in ihrer gesellschaftlichen Wahrnehmung noch immer mit Stigma behaftet — was Betroffene dazu verleiten kann, professionelle Hilfe zu zögern oder abzulehnen, was die Chronifizierung von Erkrankungen begünstigt.","english":"Mental illnesses are still beset with stigma in their social perception — which can lead those affected to hesitate in seeking or to refuse professional help, which promotes the chronification of illnesses."},{"german":"Die lange Wartezeit auf einen Therapieplatz spiegelt eine strukturelle Unterversorgung wider, die besonders jene trifft, die auf schnelle Intervention angewiesen sind.","english":"The long wait for a therapy place reflects a structural under-provision, which particularly affects those who are dependent on rapid intervention."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss mental health, stigma, and Germany''s mental healthcare system at B2."}}',
'{"items":[{"word":"behaftet mit","translation":"beset with/marked by","pronunciation":"beh-HAF-tet mit","example":"Mit Stigma behaftet."},{"word":"verleiten zu","translation":"to lead to (to induce)","pronunciation":"fer-LY-ten tsoo","example":"Zu Zögern verleiten."},{"word":"zögern","translation":"to hesitate","pronunciation":"TSÖH-gern","example":"Zögern, Hilfe zu suchen."},{"word":"die Chronifizierung","translation":"chronification","pronunciation":"dee khro-ni-fi-TSEER-oong","example":"Chronifizierung von Erkrankungen."},{"word":"begünstigen","translation":"to promote/favour","pronunciation":"beh-GÜN-stigen","example":"Chronifizierung begünstigen."},{"word":"angewiesen auf","translation":"dependent on","pronunciation":"AN-geh-vee-zen owf","example":"Auf schnelle Intervention angewiesen."}]}',
'{"title":"Auf etwas angewiesen sein — to be dependent on something (necessity, not choice)","pattern":"jemand/etwas ist auf X angewiesen = someone/something is dependent on X, is reliant on X (angewiesen = reliant — implies necessity, no alternative — stronger dependency than abhängig sein von)","explanation":"Auf X angewiesen sein = to be dependent on X, to rely on X (where there is no alternative — necessity). Jene, die auf schnelle Intervention angewiesen sind = those who are dependent on/require rapid intervention. Angewiesen (past participle used as adjective) + auf + accusative. Compare: abhängig sein von (to be dependent on — can imply addiction or reliance), brauchen (to need — more neutral), benötigen (to require — more formal neutral). Angewiesen sein auf emphasises necessity: without X, the person/thing cannot function. Perfect: ist angewiesen geblieben (rarely used — usually stays in stative present).","examples":[{"sentence":"Im Alter ist man oft auf die Hilfe anderer angewiesen.","translation":"In old age, one is often dependent on the help of others."},{"sentence":"Das System ist auf eine stabile Internetverbindung angewiesen.","translation":"The system is dependent on a stable internet connection."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Behaftet mit'' means?","options":["beset with/marked by","affected by","tainted with","labelled with"],"correctAnswer":"beset with/marked by"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Mental illnesses are still beset with stigma in their social perception — which can lead those affected to hesitate in seeking or to refuse professional help, which promotes the chronification of illnesses.","options":["Psychische Erkrankungen sind in ihrer gesellschaftlichen Wahrnehmung noch immer mit Stigma behaftet — was Betroffene dazu verleiten kann, professionelle Hilfe zu zögern oder abzulehnen, was die Chronifizierung von Erkrankungen begünstigt.","Psychische Erkrankungen werden gesellschaftlich noch stigmatisiert.","Stigma hindert viele Betroffene daran, Hilfe zu suchen.","Wegen Stigmatisierung warten Menschen zu lange, bevor sie professionelle Hilfe suchen."],"correctAnswer":"Psychische Erkrankungen sind in ihrer gesellschaftlichen Wahrnehmung noch immer mit Stigma behaftet — was Betroffene dazu verleiten kann, professionelle Hilfe zu zögern oder abzulehnen, was die Chronifizierung von Erkrankungen begünstigt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Im Alter ist man oft auf die Hilfe anderer ___.","options":["angewiesen","abhängig","angewiesen","gebunden"],"correctAnswer":"angewiesen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The system is dependent on a stable internet connection","wordBankItems":["Das","System","ist","auf","eine","stabile","Internetverbindung","angewiesen","."],"correctAnswer":"Das System ist auf eine stabile Internetverbindung angewiesen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Begünstigen'' means?","options":["to promote/favour","to encourage","to facilitate","to enable"],"correctAnswer":"to promote/favour"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000271',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss digital medicine at B2","Use Digitale Medizin vocabulary","Talk about telemedicine, health data, and AI in healthcare"],"explanation":{"intro":"Digital medicine vocabulary covers telemedicine, electronic health records, and AI in healthcare at B2.","culturalNote":"Digitale Medizin: Germany lags behind (Digitalrückstand — digital deficit in healthcare). Key tools: Elektronische Patientenakte (ePA — electronic health record, rolled out from 2025 — opt-out). Telemedizin (telemedicine — COVID accelerated). Digitale Gesundheitsanwendungen (DiGAs — digital health apps, reimbursable by GKV — unique globally). AI in Diagnostik (AI in diagnostics — radiology, pathology). Key challenges: Datenschutz (data protection — GDPR, German sensitivity), Interoperabilität (interoperability), Ärztemangel (doctor shortage). Key law: Digitale-Versorgung-Gesetz (2019)."},"examples":[{"german":"Digitale Gesundheitsanwendungen auf Rezept sind eine deutsche Innovation, die verschreibungspflichtige Apps erstattungsfähig macht — ein Experiment, das weltweit Aufmerksamkeit erregt, weil es evidenzbasierte Zulassungsverfahren auf Softwareprodukte überträgt.","english":"Digital health applications on prescription are a German innovation that makes prescription-eligible apps reimbursable — an experiment that attracts attention worldwide, because it transfers evidence-based approval procedures to software products."},{"german":"Künstliche Intelligenz in der Diagnostik verspricht sowohl eine Effizienzsteigerung als auch eine Verbesserung der Diagnosegenauigkeit — birgt aber auch Risiken hinsichtlich Haftung, Transparenz und der Arzt-Patienten-Beziehung.","english":"Artificial intelligence in diagnostics promises both an efficiency increase and an improvement in diagnostic accuracy — but also harbours risks with regard to liability, transparency, and the doctor-patient relationship."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss digital medicine, DiGAs, and AI diagnostics in German healthcare at B2."}}',
'{"items":[{"word":"erstattungsfähig","translation":"reimbursable","pronunciation":"er-SHTAT-toonks-fä-ikh","example":"Erstattungsfähige Apps."},{"word":"übertragen auf","translation":"to transfer to","pronunciation":"ü-ber-TRAH-gen owf","example":"Verfahren übertragen auf."},{"word":"versprechen","translation":"to promise","pronunciation":"fer-SHPRE-khen","example":"Effizienzsteigerung versprechen."},{"word":"bergen","translation":"to harbour/carry (risks)","pronunciation":"BER-gen","example":"Risiken bergen."},{"word":"hinsichtlich","translation":"with regard to","pronunciation":"HIN-zikht-likh","example":"Hinsichtlich Haftung."},{"word":"die Diagnosegenauigkeit","translation":"diagnostic accuracy","pronunciation":"dee dee-ag-NOH-zeh-geh-now-ikh-kyt","example":"Diagnosegenauigkeit verbessern."}]}',
'{"title":"Risiken bergen — to harbour/carry risks (bergen = to carry, hold — used with abstract dangers)","pattern":"etwas birgt Risiken/Gefahren = something harbours/carries risks (bergen = to hold/keep — in this use: to contain/harbour — irr: birgt, barg, hat geborgen)","explanation":"Bergen = to harbour, to hold (a risk or danger). Etwas birgt Risiken = something harbours/carries risks (holds potential dangers within). Irregular: birgt (present), barg (simple past), hat geborgen (perfect). Also used: in sich bergen (to harbour within itself). Etw. birgt die Gefahr, dass... = something harbours the danger that... Bergen is more literary/formal than enthalten (to contain) or haben (to have). Also: bergen = to recover (a body, a shipwreck) — different but related meaning (to retrieve what is hidden inside). Compare: mit sich bringen (to entail — more causal), implizieren (to imply — more logical), aufwerfen (to raise — for questions).","examples":[{"sentence":"Dieser Ansatz birgt die Gefahr, dass wichtige Details übersehen werden.","translation":"This approach harbours the danger that important details are overlooked."},{"sentence":"Jede Innovation birgt unvorhergesehene Risiken.","translation":"Every innovation harbours unforeseen risks."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Erstattungsfähig'' means?","options":["reimbursable","compensable","payable","eligible"],"correctAnswer":"reimbursable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Artificial intelligence in diagnostics promises both an efficiency increase and an improvement in diagnostic accuracy — but also harbours risks with regard to liability, transparency, and the doctor-patient relationship.","options":["Künstliche Intelligenz in der Diagnostik verspricht sowohl eine Effizienzsteigerung als auch eine Verbesserung der Diagnosegenauigkeit — birgt aber auch Risiken hinsichtlich Haftung, Transparenz und der Arzt-Patienten-Beziehung.","KI verbessert die medizinische Diagnose, wirft aber Datenschutzfragen auf.","Künstliche Intelligenz ist ein Fortschritt in der Medizin, der reguliert werden muss.","KI in der Medizin bietet Chancen und Risiken."],"correctAnswer":"Künstliche Intelligenz in der Diagnostik verspricht sowohl eine Effizienzsteigerung als auch eine Verbesserung der Diagnosegenauigkeit — birgt aber auch Risiken hinsichtlich Haftung, Transparenz und der Arzt-Patienten-Beziehung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Dieser Ansatz birgt die Gefahr, dass wichtige Details übersehen ___.","options":["werden","sind","bleiben","werden"],"correctAnswer":"werden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Every innovation harbours unforeseen risks","wordBankItems":["Jede","Innovation","birgt","unvorhergesehene","Risiken","."],"correctAnswer":"Jede Innovation birgt unvorhergesehene Risiken ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Hinsichtlich'' means?","options":["with regard to","regarding","concerning","in terms of"],"correctAnswer":"with regard to"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000272',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the pharmaceutical industry at B2","Use Pharmaindustrie vocabulary","Talk about drug development, pricing, and access"],"explanation":{"intro":"Pharmaceutical industry vocabulary covers drug development, pricing, and Germany''s pharmaceutical sector at B2.","culturalNote":"Pharmaindustrie: Germany is a major global pharma hub (Bayer, Boehringer Ingelheim, Merck Darmstadt). Key stages: Forschung & Entwicklung (R&D — very costly, ~10 years, $1bn average), Zulassung (approval — EMA European Medicines Agency), Patentschutz (patent protection). Key issues: Arzneimittelpreise (drug prices — Germany: AMNOG procedure — early benefit assessment), Nachahmerpräparate (generics), Orphan Drugs (für seltene Krankheiten — rare diseases). COVID vaccines: rapid mRNA development (BioNTech-Pfizer — Mainz company). Global: Preisgerechtigkeit (price justice — access to medicines in developing world). Big Pharma lobbying."},"examples":[{"german":"Der Entwicklungsprozess eines neuen Medikaments ist langwierig, kostspielig und risikobehaftet: Die meisten Wirkstoffkandidaten scheitern in der klinischen Erprobung, was die Forschungskosten auf die wenigen erfolgreichen Produkte konzentriert.","english":"The development process of a new medicine is protracted, costly, and laden with risk: most active substance candidates fail in clinical testing, which concentrates the research costs on the few successful products."},{"german":"Die Balance zwischen Anreizen für pharmazeutische Innovation und dem Zugang zu erschwinglichen Arzneimitteln bleibt eines der schwierigsten Regulierungsprobleme im Gesundheitswesen.","english":"The balance between incentives for pharmaceutical innovation and access to affordable medicines remains one of the most difficult regulatory problems in healthcare."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss drug development, pharmaceutical pricing, and access to medicines at B2."}}',
'{"items":[{"word":"langwierig","translation":"protracted/long-winded","pronunciation":"LANG-vee-rikh","example":"Langwieriger Prozess."},{"word":"risikobehaftet","translation":"laden with risk","pronunciation":"ri-ZEE-ko-beh-haf-tet","example":"Risikobehaftet sein."},{"word":"scheitern","translation":"to fail","pronunciation":"SHYE-tern","example":"In Erprobung scheitern."},{"word":"die Erprobung","translation":"testing/trial","pronunciation":"dee er-PROH-boong","example":"Klinische Erprobung."},{"word":"erschwinglich","translation":"affordable","pronunciation":"er-SHVING-likh","example":"Erschwingliche Arzneimittel."},{"word":"der Anreiz","translation":"incentive","pronunciation":"dayr AN-rits","example":"Anreize für Innovation."}]}',
'{"title":"Etwas konzentriert sich auf X — to be concentrated in/on X (passive-like active)","pattern":"etwas konzentriert X auf Y = something concentrates X on Y (active: the external force concentrates); etwas konzentriert sich auf Y = X is concentrated on Y (reflexive: X is self-concentrated — often describing distributions)","explanation":"Konzentrieren (+ sich): transitive = to concentrate X on Y; reflexive = X is concentrated in/on Y (describing where something is clustered). Was die Forschungskosten auf erfolgreiche Produkte konzentriert = which concentrates research costs on successful products (active — the mechanism concentrates). Die Kosten konzentrieren sich auf wenige Produkte = The costs are concentrated on a few products (reflexive). Both forms common — use active when describing an external mechanism, reflexive when describing the distribution state.","examples":[{"sentence":"Die Macht konzentriert sich in wenigen Händen.","translation":"Power is concentrated in few hands."},{"sentence":"Die Investitionen konzentrieren sich auf städtische Gebiete.","translation":"The investments are concentrated in urban areas."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Langwierig'' means?","options":["protracted/long-winded","lengthy","slow","drawn-out"],"correctAnswer":"protracted/long-winded"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The development process of a new medicine is protracted, costly, and laden with risk: most active substance candidates fail in clinical testing, which concentrates the research costs on the few successful products.","options":["Der Entwicklungsprozess eines neuen Medikaments ist langwierig, kostspielig und risikobehaftet: Die meisten Wirkstoffkandidaten scheitern in der klinischen Erprobung, was die Forschungskosten auf die wenigen erfolgreichen Produkte konzentriert.","Neue Medikamente zu entwickeln ist teuer und dauert lang.","Pharmaforschung ist sehr riskant, weil die meisten Wirkstoffe scheitern.","Die Kosten der Pharmaforschung entstehen hauptsächlich durch gescheiterte Projekte."],"correctAnswer":"Der Entwicklungsprozess eines neuen Medikaments ist langwierig, kostspielig und risikobehaftet: Die meisten Wirkstoffkandidaten scheitern in der klinischen Erprobung, was die Forschungskosten auf die wenigen erfolgreichen Produkte konzentriert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Macht konzentriert sich in wenigen ___.","options":["Händen","Stellen","Orten","Zentren"],"correctAnswer":"Händen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The investments are concentrated in urban areas","wordBankItems":["Die","Investitionen","konzentrieren","sich","auf","städtische","Gebiete","."],"correctAnswer":"Die Investitionen konzentrieren sich auf städtische Gebiete ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erschwinglich'' means?","options":["affordable","accessible","cheap","reasonable"],"correctAnswer":"affordable"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000273',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss health inequality at B2","Use Gesundheitsungleichheit vocabulary","Talk about social determinants of health and health disparities"],"explanation":{"intro":"Health inequality vocabulary covers social determinants of health, disparities, and Germany''s healthcare access gaps at B2.","culturalNote":"Gesundheitsungleichheit: socioeconomic status (SES) strongly predicts health outcomes. Germany: Sozialstatus und Gesundheit (social status and health — Robert Koch-Institut reports). Lower income → less healthy diet, more stress, less access to health literacy, higher smoking rates. Key disparities: Bildungsungleichheit (educational inequality) affects Gesundheitskompetenz (health literacy). Stadtland-Unterschiede (urban-rural differences). Migration und Gesundheit (migrants face language barriers, precarious work). Key concept: Soziale Determinanten der Gesundheit (social determinants of health — WHO framework: income, education, housing, work). Germany: GKV-Spitzenverband, report on health inequalities."},"examples":[{"german":"Gesundheitliche Ungleichheit ist nicht auf biologische Unterschiede, sondern auf soziale Determinanten wie Einkommen, Bildung, Wohnbedingungen und Arbeit zurückzuführen — eine Erkenntnis, die präventive Gesundheitspolitik über den rein medizinischen Sektor hinaus fordert.","english":"Health inequality is attributable not to biological differences, but to social determinants such as income, education, housing conditions, and work — an insight that demands preventive health policy beyond the purely medical sector."},{"german":"Gesundheitskompetenz — die Fähigkeit, gesundheitsbezogene Informationen zu finden, zu verstehen und anzuwenden — ist ungleich verteilt und hängt stark mit Bildungsniveau und sozioökonomischem Status zusammen.","english":"Health literacy — the ability to find, understand, and apply health-related information — is unequally distributed and is strongly correlated with level of education and socioeconomic status."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss health inequalities, social determinants of health, and health literacy at B2."}}',
'{"items":[{"word":"zurückzuführen auf","translation":"attributable to","pronunciation":"tsoo-RÜK-tsoo-fü-ren owf","example":"Auf soziale Ursachen zurückzuführen."},{"word":"die Determinante","translation":"determinant","pronunciation":"dee deh-ter-mi-NAN-teh","example":"Soziale Determinanten."},{"word":"über X hinaus","translation":"beyond X","pronunciation":"ü-ber X hi-NOWS","example":"Über den Sektor hinaus."},{"word":"zusammenhängen mit","translation":"to be correlated with","pronunciation":"tsoo-ZA-men-häng-en mit","example":"Mit Status zusammenhängen."},{"word":"die Gesundheitskompetenz","translation":"health literacy","pronunciation":"dee geh-ZOONT-hyts-kom-peh-tents","example":"Gesundheitskompetenz."},{"word":"ungleich verteilt","translation":"unequally distributed","pronunciation":"oon-GLYKH fer-tylt","example":"Ungleich verteilt."}]}',
'{"title":"Auf etwas zurückzuführen sein — to be attributable to something (causal explanation)","pattern":"etwas ist auf X zurückzuführen = something is attributable to X (zurückführen auf = to attribute to; passive infinitive: ist...zurückzuführen — infinitive passive, z infinitive construction)","explanation":"Auf X zurückzuführen sein = to be attributable to X. This is an infinitive passive construction (not a full passive): ist + zurückzuführen (infinitive of the separable verb zurückführen). Ungleichheit ist auf soziale Determinanten zurückzuführen = Inequality is attributable to social determinants. Compare: liegt an (is due to — more colloquial), beruht auf (is based on — used for more foundational explanations), hängt zusammen mit (is correlated with — not necessarily causal), geht zurück auf (goes back to/dates back to — historical origin).","examples":[{"sentence":"Der Anstieg ist auf veränderte Konsumgewohnheiten zurückzuführen.","translation":"The increase is attributable to changed consumption habits."},{"sentence":"Die Fehler sind auf mangelnde Kommunikation zurückzuführen.","translation":"The errors are attributable to insufficient communication."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ungleich verteilt'' means?","options":["unequally distributed","uneven","skewed","asymmetric"],"correctAnswer":"unequally distributed"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Health inequality is attributable not to biological differences, but to social determinants such as income, education, housing conditions, and work — an insight that demands preventive health policy beyond the purely medical sector.","options":["Gesundheitliche Ungleichheit ist nicht auf biologische Unterschiede, sondern auf soziale Determinanten wie Einkommen, Bildung, Wohnbedingungen und Arbeit zurückzuführen — eine Erkenntnis, die präventive Gesundheitspolitik über den rein medizinischen Sektor hinaus fordert.","Gesundheitliche Unterschiede zwischen sozialen Gruppen haben soziale Ursachen.","Prävention muss soziale Faktoren berücksichtigen, nicht nur medizinische.","Sozialer Status beeinflusst Gesundheit stärker als biologische Faktoren."],"correctAnswer":"Gesundheitliche Ungleichheit ist nicht auf biologische Unterschiede, sondern auf soziale Determinanten wie Einkommen, Bildung, Wohnbedingungen und Arbeit zurückzuführen — eine Erkenntnis, die präventive Gesundheitspolitik über den rein medizinischen Sektor hinaus fordert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Anstieg ist auf veränderte Konsumgewohnheiten ___.","options":["zurückzuführen","zurückzugehen","zurückzulenken","zurückzulegen"],"correctAnswer":"zurückzuführen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The errors are attributable to insufficient communication","wordBankItems":["Die","Fehler","sind","auf","mangelnde","Kommunikation","zurückzuführen","."],"correctAnswer":"Die Fehler sind auf mangelnde Kommunikation zurückzuführen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Zusammenhängen mit'' means?","options":["to be correlated with","to be connected to","to relate to","to depend on"],"correctAnswer":"to be correlated with"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000274',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss pandemic preparedness at B2","Use Pandemievorsorge vocabulary","Talk about Germany''s COVID experience and pandemic readiness"],"explanation":{"intro":"Pandemic preparedness vocabulary covers infectious disease surveillance, response mechanisms, and lessons from COVID at B2.","culturalNote":"Pandemievorsorge: Germany''s COVID-19 experience: initial testing success, then second wave struggles. Robert Koch-Institut (RKI — key epidemiological authority), Bundesgesundheitsminister (Federal Health Minister). Key measures: Lockdown, Kurzarbeit, Wirtschaftshilfen. Impfstoff-Entwicklung (vaccine development — BioNTech, Mainz — mRNA technology). Impfpflicht-Debatte (vaccination mandate debate — not introduced). Lessons: Materiallager (stockpiles), Surveillance-Kapazität, Koordination Bund-Länder (federal-state coordination — a major weakness). Global: WHO pandemic treaty negotiations (2024-2025), International Health Regulations. Key concept: One Health (human, animal, environmental health)."},"examples":[{"german":"Die COVID-19-Pandemie hat gezeigt, dass belastbare Pandemievorsorge kontinuierliche Investitionen in Surveillance, Diagnostikkapazitäten, Materiallager und internationale Koordination erfordert — nicht reaktives Krisenmanagement nach Ausbruch.","english":"The COVID-19 pandemic has shown that robust pandemic preparedness requires continuous investments in surveillance, diagnostic capacities, stockpiles, and international coordination — not reactive crisis management after the outbreak."},{"german":"Die Spannungen zwischen Bund und Ländern während der Pandemie verdeutlichten die strukturellen Grenzen des föderalen Systems in nationalen Notlagen, in denen schnelle und kohärente Entscheidungen überlebenswichtig sein können.","english":"The tensions between federal government and states during the pandemic made clear the structural limits of the federal system in national emergencies, in which rapid and coherent decisions can be vital."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss pandemic preparedness, Germany''s COVID response, and federalism''s role in crises at B2."}}',
'{"items":[{"word":"belastbar","translation":"robust/resilient","pronunciation":"beh-LAST-bar","example":"Belastbare Vorsorge."},{"word":"kontinuierlich","translation":"continuous","pronunciation":"kon-ti-noo-EER-likh","example":"Kontinuierliche Investitionen."},{"word":"reaktiv","translation":"reactive","pronunciation":"reh-ak-TEEF","example":"Reaktives Krisenmanagement."},{"word":"kohärent","translation":"coherent","pronunciation":"ko-hä-RENT","example":"Kohärente Entscheidungen."},{"word":"überlebenswichtig","translation":"vital/crucial for survival","pronunciation":"ü-ber-LAY-bens-vikh-tikh","example":"Überlebenswichtig sein."},{"word":"die Notlage","translation":"emergency/distress situation","pronunciation":"dee NOHT-lah-geh","example":"Nationale Notlage."}]}',
'{"title":"Nicht X, sondern Y — not X, but Y (correction — sharper than aber)","pattern":"nicht X, sondern Y = not X, but Y (sondern = but — used ONLY after a negation; corrects or replaces the negated element; sharper contrast than aber)","explanation":"Nicht...sondern = not...but (sondern: always after negation — replaces the negated element with the correct alternative). Nicht reaktives Krisenmanagement, sondern kontinuierliche Investitionen = Not reactive crisis management, but continuous investments (sondern corrects the negated nicht X to the right answer Y). Aber = but (additive contrast — can come after positive or negative), sondern = but (corrective negation — ONLY after nicht/kein). Nicht...sondern is stronger and more precise: it explicitly excludes X and inserts Y. Test: can you replace sondern with aber? Only if there is no negation before it.","examples":[{"sentence":"Es geht nicht um Kosten, sondern um Qualität.","translation":"It is not about cost, but about quality."},{"sentence":"Nicht der Zeitplan, sondern die Qualität steht im Vordergrund.","translation":"Not the timeline, but quality is in the foreground."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Belastbar'' means?","options":["robust/resilient","reliable","sturdy","dependable"],"correctAnswer":"robust/resilient"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The COVID-19 pandemic has shown that robust pandemic preparedness requires continuous investments in surveillance, diagnostic capacities, stockpiles, and international coordination — not reactive crisis management after the outbreak.","options":["Die COVID-19-Pandemie hat gezeigt, dass belastbare Pandemievorsorge kontinuierliche Investitionen in Surveillance, Diagnostikkapazitäten, Materiallager und internationale Koordination erfordert — nicht reaktives Krisenmanagement nach Ausbruch.","COVID hat gezeigt, dass Pandemievorsorge dauerhaft finanziert werden muss.","Gute Pandemievorsorge bedeutet Investitionen vor, nicht nach einem Ausbruch.","Surveillance und internationale Koordination sind entscheidend für die Pandemievorsorge."],"correctAnswer":"Die COVID-19-Pandemie hat gezeigt, dass belastbare Pandemievorsorge kontinuierliche Investitionen in Surveillance, Diagnostikkapazitäten, Materiallager und internationale Koordination erfordert — nicht reaktives Krisenmanagement nach Ausbruch."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Es geht nicht um Kosten, sondern um ___.","options":["Qualität","Effizienz","Ergebnis","Leistung"],"correctAnswer":"Qualität"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Not the timeline but quality is in the foreground","wordBankItems":["Nicht","der","Zeitplan",",","sondern","die","Qualität","steht","im","Vordergrund","."],"correctAnswer":"Nicht der Zeitplan , sondern die Qualität steht im Vordergrund ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Überlebenswichtig'' means?","options":["vital/crucial for survival","essential","critical","life-or-death"],"correctAnswer":"vital/crucial for survival"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000275',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss care services at B2","Use Pflegeversorgung vocabulary","Talk about Germany''s care crisis and long-term care"],"explanation":{"intro":"Care services vocabulary covers long-term care, Germany''s Pflegeversicherung, and the growing care crisis at B2.","culturalNote":"Pflegeversorgung: Pflegeversicherung (long-term care insurance — 5th pillar of German social insurance, since 1995). Pflegegrade (care levels 1-5). Pflege zu Hause (home care — majority) vs. stationäre Pflege (residential care). Crisis factors: Demographischer Wandel (demographic change — more elderly), Fachkräftemangel in der Pflege (nursing shortage — underpaid, overworked), Finanzierungslücke (funding gap). Pflegereform (care reform — ongoing debate). Key institutions: AWO, Caritas, Diakonie. Care workers: largely female, often from Eastern Europe. Key concept: Pflegegeld (care allowance — for informal carers)."},"examples":[{"german":"Die Pflegeversicherung steht vor einer strukturellen Herausforderung: Eine alternde Gesellschaft mit wachsendem Pflegebedarf trifft auf schrumpfende Beitragszahlerbasis und Fachkräftemangel — ein Spannungsverhältnis, das ohne grundlegende Reformen nicht aufzulösen ist.","english":"Long-term care insurance faces a structural challenge: an ageing society with growing care needs meets a shrinking contributor base and shortage of skilled workers — a tension that cannot be resolved without fundamental reforms."},{"german":"Pflege ist gegenwärtig stark feminisiert und unterbezahlt: Die gesellschaftliche Geringschätzung eines systemrelevanten Berufs spiegelt tiefere geschlechterspezifische Bewertungsmuster wider.","english":"Care work is currently heavily feminised and underpaid: the societal undervaluation of an occupation relevant to the functioning of the system reflects deeper gender-specific valuation patterns."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s care insurance, nursing shortage, and care work''s undervaluation at B2."}}',
'{"items":[{"word":"alternde Gesellschaft","translation":"ageing society","pronunciation":"AL-tern-deh geh-ZEL-shaft","example":"Alternde Gesellschaft."},{"word":"die Beitragszahlerbasis","translation":"contributor base","pronunciation":"dee BY-trags-tsah-ler-bah-zis","example":"Beitragszahlerbasis."},{"word":"auflösen","translation":"to resolve","pronunciation":"OWF-lö-zen","example":"Ein Spannungsverhältnis auflösen."},{"word":"feminisiert","translation":"feminised","pronunciation":"feh-mi-ni-ZEERT","example":"Stark feminisiert."},{"word":"die Geringschätzung","translation":"undervaluation","pronunciation":"dee geh-RING-shä-tsoong","example":"Gesellschaftliche Geringschätzung."},{"word":"systemrelevant","translation":"essential to the system","pronunciation":"zys-TEM-reh-leh-vant","example":"Systemrelevanter Beruf."}]}',
'{"title":"Ohne X zu + infinitive — without X-ing / without doing X","pattern":"ohne X zu + infinitive = without X-ing (ohne...zu = without + infinitive; X is the implied subject of the infinitive — same person as main clause subject)","explanation":"Ohne...zu + infinitive = without doing X (same subject as main clause). Ein Spannungsverhältnis, das ohne grundlegende Reformen nicht aufzulösen ist = A tension that cannot be resolved without fundamental reforms. Here: ohne + Reformen (noun — without reforms, a reform-less case). Also: ohne etwas zu tun (without doing something): ohne zu zahlen (without paying), ohne zu fragen (without asking). This is one of the ''um/ohne/statt + zu'' group — all require zu + infinitive (not dass-clause) when same subject: Er geht, ohne zu zahlen (he goes without paying). Different subject → ohne dass + full clause: Er geht, ohne dass sie es merkt (he goes without her noticing).","examples":[{"sentence":"Sie arbeiteten weiter, ohne sich zu beklagen.","translation":"They kept working without complaining."},{"sentence":"Man kann nicht verhandeln, ohne Kompromisse einzugehen.","translation":"One cannot negotiate without making compromises."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Systemrelevant'' means?","options":["essential to the system","systemically important","critical","infrastructure"],"correctAnswer":"essential to the system"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Long-term care insurance faces a structural challenge: an ageing society with growing care needs meets a shrinking contributor base and shortage of skilled workers — a tension that cannot be resolved without fundamental reforms.","options":["Die Pflegeversicherung steht vor einer strukturellen Herausforderung: Eine alternde Gesellschaft mit wachsendem Pflegebedarf trifft auf schrumpfende Beitragszahlerbasis und Fachkräftemangel — ein Spannungsverhältnis, das ohne grundlegende Reformen nicht aufzulösen ist.","Die Pflegeversicherung hat finanzielle und personelle Probleme.","Die Pflegekrise ist Folge des demografischen Wandels und des Fachkräftemangels.","Die Pflegeversicherung braucht eine Reform, um zahlungsfähig zu bleiben."],"correctAnswer":"Die Pflegeversicherung steht vor einer strukturellen Herausforderung: Eine alternde Gesellschaft mit wachsendem Pflegebedarf trifft auf schrumpfende Beitragszahlerbasis und Fachkräftemangel — ein Spannungsverhältnis, das ohne grundlegende Reformen nicht aufzulösen ist."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Man kann nicht verhandeln, ohne Kompromisse ___.","options":["einzugehen","einzuhalten","einzubringen","einzuräumen"],"correctAnswer":"einzugehen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: They kept working without complaining","wordBankItems":["Sie","arbeiteten","weiter",",","ohne","sich","zu","beklagen","."],"correctAnswer":"Sie arbeiteten weiter , ohne sich zu beklagen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Geringschätzung'' means?","options":["undervaluation","contempt","disrespect","neglect"],"correctAnswer":"undervaluation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000276',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss health economics at B2","Use Gesundheitsökonomie vocabulary","Talk about healthcare costs, efficiency, and value-based care"],"explanation":{"intro":"Health economics vocabulary covers healthcare financing, efficiency, and the economics of medical interventions at B2.","culturalNote":"Gesundheitsökonomie: Germany''s healthcare spending: ~12% of GDP (among highest in OECD). Key concepts: Krankheitslast (burden of disease — DALYs), Kosteneffektivität (cost-effectiveness — QALY = quality-adjusted life year), Opportunitätskosten (opportunity costs). AMNOG (Arzneimittelmarktneuordnungsgesetz — 2010 — early benefit assessment for new drugs — IQWIG assessment). Priorisierungsdebatte (prioritisation debate — which treatments to fund). Key principle: QALY-Analyse (quality-adjusted life year — used in UK''s NICE, less so in Germany). Key challenge: cost containment (Kostendämpfung) vs. access (Zugang)."},"examples":[{"german":"Die Gesundheitsökonomie stellt die Frage, wie begrenzte Mittel so eingesetzt werden können, dass sie den größtmöglichen gesundheitlichen Nutzen erzeugen — eine Abwägung, die implizit ethische Urteile darüber trifft, welche Gesundheitsgewinne wie viel wert sind.","english":"Health economics poses the question of how limited resources can be deployed such that they produce the greatest possible health benefit — a weighing of values that implicitly makes ethical judgements about how much certain health gains are worth."},{"german":"Das Konzept der qualitätsbereinigten Lebensjahre (QALYs) ermöglicht die Vergleichbarkeit unterschiedlicher Gesundheitsinterventionen, wird aber gleichzeitig dafür kritisiert, dass es das Leben älterer oder behinderter Menschen systematisch geringer bewertet.","english":"The concept of quality-adjusted life years (QALYs) enables the comparability of different health interventions, but is at the same time criticised for the fact that it systematically values the lives of older or disabled people lower."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss health economics, QALYs, and cost-effectiveness in German healthcare at B2."}}',
'{"items":[{"word":"begrenzt","translation":"limited","pronunciation":"beh-GRENZT","example":"Begrenzte Mittel."},{"word":"einsetzen","translation":"to deploy/use","pronunciation":"YN-set-sen","example":"Mittel einsetzen."},{"word":"der Gesundheitsgewinn","translation":"health gain","pronunciation":"dayr geh-ZOONT-hyts-geh-vin","example":"Größter Gesundheitsgewinn."},{"word":"implizit","translation":"implicitly","pronunciation":"im-pli-TSEET","example":"Implizit ethische Urteile."},{"word":"die Vergleichbarkeit","translation":"comparability","pronunciation":"dee fer-GLYKH-bahr-kyt","example":"Vergleichbarkeit ermöglichen."},{"word":"systematisch","translation":"systematically","pronunciation":"zys-teh-MAH-tish","example":"Systematisch geringer bewerten."}]}',
'{"title":"Dafür kritisiert werden, dass... — to be criticised for the fact that... (criticism + content clause)","pattern":"etwas wird dafür kritisiert, dass = something is criticised for the fact that (dafür...dass = correlative pair — dafür in main clause, dass-clause gives the content of the criticism)","explanation":"Dafür kritisiert werden, dass = to be criticised for the fact that (passive criticism + content). Dafür + dass-clause: correlative (dafür anticipates the dass-clause). Das Konzept wird dafür kritisiert, dass es das Leben älterer Menschen geringer bewertet = The concept is criticised for the fact that it values older people''s lives lower. The pair dafür...dass is also used with other verbs: dafür loben/bekannt/gefeiert werden, dass (to be praised/known/celebrated for the fact that). Compare: wegen + genitive (because of — more neutral, less content-rich), aufgrund von (on account of).","examples":[{"sentence":"Die Maßnahme wird dafür kritisiert, dass sie zu weit geht.","translation":"The measure is criticised for the fact that it goes too far."},{"sentence":"Er wurde dafür gelobt, dass er Verantwortung übernahm.","translation":"He was praised for the fact that he took responsibility."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Vergleichbarkeit'' means?","options":["comparability","comparison","equivalence","parallelism"],"correctAnswer":"comparability"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Health economics poses the question of how limited resources can be deployed such that they produce the greatest possible health benefit — a weighing of values that implicitly makes ethical judgements about how much certain health gains are worth.","options":["Die Gesundheitsökonomie stellt die Frage, wie begrenzte Mittel so eingesetzt werden können, dass sie den größtmöglichen gesundheitlichen Nutzen erzeugen — eine Abwägung, die implizit ethische Urteile darüber trifft, welche Gesundheitsgewinne wie viel wert sind.","Gesundheitsökonomie fragt, wie man mit begrenzten Mitteln den größten Nutzen erzielt.","Die Ressourcenallokation im Gesundheitswesen hat immer eine ethische Dimension.","Wie viel ist ein gesundes Lebensjahr wert? Das ist die Frage der Gesundheitsökonomie."],"correctAnswer":"Die Gesundheitsökonomie stellt die Frage, wie begrenzte Mittel so eingesetzt werden können, dass sie den größtmöglichen gesundheitlichen Nutzen erzeugen — eine Abwägung, die implizit ethische Urteile darüber trifft, welche Gesundheitsgewinne wie viel wert sind."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Maßnahme wird dafür kritisiert, dass sie zu weit ___.","options":["geht","reicht","führt","zielt"],"correctAnswer":"geht"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He was praised for the fact that he took responsibility","wordBankItems":["Er","wurde","dafür","gelobt",",","dass","er","Verantwortung","übernahm","."],"correctAnswer":"Er wurde dafür gelobt , dass er Verantwortung übernahm ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Implizit'' means?","options":["implicitly","tacitly","covertly","unstated"],"correctAnswer":"implicitly"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

